from pathlib import Path
from playwright.sync_api import sync_playwright
import json,hashlib,os,shutil
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'test-results';OUT.mkdir(exist_ok=True)
checks=[]
def ok(name,condition):
 if not condition:raise AssertionError(name)
 checks.append(name)
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or shutil.which('chromium') or None,headless=True,args=['--no-sandbox'])
 context=browser.new_context(viewport={'width':1440,'height':1100},accept_downloads=True)
 page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content((ROOT/'package/UTI360X_Gestao_Offline.html').read_text(),wait_until='load');page.wait_for_function("typeof UTIGestaoApp !== 'undefined'")
 ok('140 itens preservados',page.evaluate('UTIGestaoApp.data.items.length')==140)
 ok('35 observações preservadas',page.evaluate('UTIGestaoApp.data.references.length')==35)
 ok('checkout desativado',page.evaluate('UTIGestao.BILLING_ENABLED') is False)
 ok('sem overflow desktop',page.evaluate('document.documentElement.scrollWidth <= innerWidth'))
 page.evaluate('window.scrollTo(0,0)');page.wait_for_timeout(150);page.screenshot(path=str(OUT/'desktop.png'),full_page=True)
 for view in ['catalogo','compras','referencias','orcamento','produto','inicio']:
  page.locator(f'#nav [data-page="{view}"]').click();ok('navegação '+view,page.locator('#'+view).is_visible())
 page.locator('#demo').click();ok('demo adiciona 3 compras',page.evaluate('UTIGestaoApp.getState().purchases.length')==3)
 ok('demo marcada explicitamente',page.locator('#demoFlag').is_visible())
 page.locator('#nav [data-page="compras"]').click();ok('alerta fictício calculado','Prioridade' in page.locator('#purchaseRows').inner_text())
 page.locator('[data-audit]').first.click();ok('diálogo de análise abre',page.locator('#dialog').is_visible());page.locator('#closeDialog').click()
 with page.expect_download() as dl:page.locator('#report').click()
 report=dl.value;report.save_as(str(OUT/'relatorio-demo.html'))
 text=Path(OUT/'relatorio-demo.html').read_text();ok('relatório explicita demo','DEMONSTRAÇÃO' in text);ok('relatório sem script','<script' not in text.lower())
 with page.expect_download() as dl:page.locator('#save').click()
 session=dl.value;session.save_as(str(OUT/'sessao-demo.json'))
 page.locator('#restore').set_input_files(str(OUT/'sessao-demo.json'))
 page.on('dialog',lambda dialog:dialog.accept())
 page.locator('#restore').set_input_files(str(OUT/'sessao-demo.json'))
 page.wait_for_timeout(150)
 ok('restauração invalida confirmação de compra',page.evaluate('UTIGestaoApp.getState().purchases.every(x=>!x.confirmed)'))
 ok('restauração invalida equivalência de referências',page.evaluate('UTIGestaoApp.getState().references.every(x=>!x.equivalent)'))
 ok('restauração mantém marca sintética',page.evaluate('UTIGestaoApp.getState().references.every(x=>x.demo)'))
 page.locator('#nav [data-page="orcamento"]').click()
 for key in ['pessoal','medicamentos','materiais','servicos','infraestrutura','outros']:page.locator(f'[data-b="{key}"]').fill('100')
 page.locator('[data-b="depreciation"]').fill('60');page.locator('#bConfirmed').check()
 ok('orçamento reconcilia 660 reais','660,00' in page.locator('#budgetResult').inner_text())
 page.locator('[data-b="pessoal"]').fill('200');ok('edição invalida reconciliação',not page.locator('#bConfirmed').is_checked())
 page.locator('[data-b="occupancy"]').fill('0');ok('denominador zero bloqueia','bloqueado' in page.locator('#budgetResult').inner_text())
 page.locator('#nav [data-page="produto"]').click()
 for k,v in [('Price','100'),('Sales','10'),('Fee','5'),('Tax','5'),('Support','10'),('Fixed','200')]:page.locator('#e'+k).fill(v)
 ok('simulador comercial calcula 600 reais','600,00' in page.locator('#economics').inner_text())
 ok('vendas desativadas na UI',page.locator('#produto button[disabled]').count()==2)
 page.locator('#nav [data-page="catalogo"]').click();page.locator('#search').fill('E01');ok('busca E01 encontra item',page.locator('#catalogRows tr').count()==1)
 with page.expect_download() as dl:page.locator('#excel').click()
 excel=dl.value;excel.save_as(str(OUT/'excel.xlsx'));ok('Excel mantém hash',hashlib.sha256((OUT/'excel.xlsx').read_bytes()).hexdigest()=='27bf900e427ae9208562a0f26c077f83fcf86eaff3479494730a447d94cf2ed6')
 page.set_viewport_size({'width':390,'height':844})
 for view in ['inicio','catalogo','compras','referencias','orcamento','produto']:
  page.locator(f'#nav [data-page="{view}"]').click();ok('sem overflow mobile '+view,page.evaluate('document.documentElement.scrollWidth <= innerWidth'))
 page.locator('#nav [data-page="inicio"]').click();page.locator('#theme').click();page.evaluate("document.getElementById('toast').hidden=true;window.scrollTo(0,0)");page.wait_for_timeout(100);page.screenshot(path=str(OUT/'mobile-dark.png'),full_page=True)
 page.locator('#font').click();ok('texto ampliado funciona',page.evaluate("document.documentElement.classList.contains('large')"))
 page.locator('#focus').click();ok('modo foco funciona',page.evaluate("document.body.classList.contains('focus')"))
 ok('sem erros JavaScript',not errors)
 fresh=context.new_page();fresh.set_content((ROOT/'package/UTI360X_Gestao_Offline.html').read_text(),wait_until='load');fresh.wait_for_function("typeof UTIGestaoApp !== 'undefined'");fresh.locator('#nav [data-page="compras"]').click()
 date=fresh.evaluate('UTIGestao.today()')
 purchasecsv='sku;data;documento;preco_embalagem;unidades_base;quantidade_embalagens\nE01;'+date+';<img src=x onerror=alert(1)>;130000;1;2'
 fresh.locator('#pImport').set_input_files({'name':'compras.csv','mimeType':'text/csv','buffer':purchasecsv.encode()})
 fresh.wait_for_selector('#commitImport');ok('prévia não altera carteira',fresh.evaluate('UTIGestaoApp.getState().purchases.length')==0)
 fresh.locator('#commitImport').click();ok('importa compra pendente',fresh.evaluate('UTIGestaoApp.getState().purchases[0].confirmed') is False)
 ok('texto importado não executa HTML',fresh.locator('#purchaseRows img').count()==0)
 with fresh.expect_download() as dl:fresh.locator('#report').click()
 dl.value.save_as(str(OUT/'relatorio-escape.html'));safe=(OUT/'relatorio-escape.html').read_text();ok('HTML escapado em relatório','&lt;img' in safe and '<img src=x' not in safe)
 fresh.locator('#pImport').set_input_files({'name':'compras.csv','mimeType':'text/csv','buffer':purchasecsv.encode()});fresh.wait_for_timeout(100);ok('duplicidade não altera carteira',fresh.evaluate('UTIGestaoApp.getState().purchases.length')==1)
 fresh.locator('#nav [data-page="referencias"]').click()
 refcsv='sku;data;instituicao;processo;preco_embalagem;unidades_base;url;marca;observacoes\n'+'\n'.join('E01;'+date+';Fixture '+str(i)+';Teste '+str(i)+';'+str(price)+';1;https://example.org/test-'+str(i)+';Teste;Dado sintético de teste de software' for i,price in enumerate([90000,100000,110000]))
 fresh.locator('#rImport').set_input_files({'name':'refs.csv','mimeType':'text/csv','buffer':refcsv.encode()});fresh.wait_for_selector('#commitImport');fresh.locator('#commitImport').click()
 ok('referências importadas começam pendentes',fresh.evaluate('UTIGestaoApp.getState().references.every(r=>!r.equivalent)'))
 for i in range(3):
  fresh.locator('[data-review="'+str(i)+'"]').click();fresh.locator('#reviewRef').check();fresh.locator('#finishRef').click()
 ok('revisão individual de referências',fresh.evaluate('UTIGestaoApp.getState().references.every(r=>r.equivalent)'))
 fresh.locator('#nav [data-page="compras"]').click();fresh.locator('[data-confirm]').click();fresh.locator('#confirmPurchase').check();fresh.locator('#finishPurchase').click()
 ok('triagem liberada só após confirmações','Prioridade' in fresh.locator('#purchaseRows').inner_text())
 result={'ok':True,'count':len(checks),'checks':checks,'errors':errors,'source':'in-memory HTML rendering; network/file navigation restricted in original authoring environment','usesSyntheticDataOnly':True}
 (OUT/'browser-results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False))
 browser.close()
